-- Aggregate counts and fingerprints only; no player/account identities in output.
begin read only; select clock_timestamp() captured_at,t.id team_id,count(distinct b.pilot_match_id)::int contexts,count(distinct ev.id)::int events,count(distinct ev.id) filter(where ev.payload->>'kind'='basic_participants')::int callup_events,md5(coalesce(string_agg(distinct ev::text, '' order by ev::text),'')) event_fingerprint from public.teams t join public.seasons s on s.id=t.season_id left join public.federation_team_entries e on e.club_team_id=t.id left join public.federation_match_teams mt on mt.entry_id=e.id left join public.basic_match_contexts b on b.catalogue_match_id=mt.match_id left join public.pilot_events ev on ev.match_id=b.pilot_match_id where t.club_id='a48efe2f-c218-633e-6be6-4ce26e61f5cd' and s.label='2026/27' group by t.id order by t.id; rollback;
